(async()=>{const out={};for(const removed of [false,true])for(const api of ['promise','digest','digestBefore']){const f=document.createElement('iframe');document.body.appendChild(f);const w=f.contentWindow,log=[];w.log=log;const childCallback=w.eval('(v=>log.push("child"))');const make=w.eval(api==='promise'?'(()=>{Promise.resolve().then(()=>log.push("internal"));queueMicrotask(()=>log.push("microtask"));return Promise.resolve(7)})':'((s)=>()=>s.digest("SHA-256",new Uint8Array([1,2])))(crypto.subtle)');const before=api==='digestBefore'?make():null;if(removed)f.remove();const p=before||make();p.then(()=>log.push('parent'));p.then(childCallback);Promise.resolve(p).then(()=>log.push('assimilated'));await new Promise(r=>setTimeout(r,40));out[removed+':'+api]=log;if(!removed)f.remove()}return out})()
